// Result contains the parsed configuration and warnings produced while loading it.
type Result struct {
	Config   *Config
	Warnings []string
}

func Load(path string) (*Result, error) {
	v := viper.New()
	v.SetEnvPrefix("FLIPT")
	v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
	v.AutomaticEnv()

	v.SetConfigFile(path)

	if err := v.ReadInConfig(); err != nil {
		return nil, fmt.Errorf("loading configuration: %w", err)
	}

	var (
		cfg        = &Config{}
		warnings   = cfg.deprecations(v)
		validators = cfg.prepare(v)
	)

	if err := v.Unmarshal(cfg, viper.DecodeHook(decodeHooks)); err != nil {
		return nil, err
	}

	// run any validation steps
	for _, validator := range validators {
		if err := validator.validate(); err != nil {
			return nil, err
		}
	}

	return &Result{Config: cfg, Warnings: warnings}, nil
}

